Q: Non-overridable reference getter A: <p>You should modify A so it cannot be assigned a new instance, see : <a href="https://godbolt.org/z/8K78WKMsx" rel="nofollow noreferrer">https://godbolt.org/z/8K78WKMsx</a>,</p>
<pre><code>class A {
public:
    A() = default;
    ~A() = default;
    A(const A&amp;) = delete;
    A&amp; operator=(const A&amp;) = delete;
    int i = 0;
};

class B {
private:
    A _a;
public:
    A &amp;getA(); // getter
};

int main() {
    B b;
    b.getA().i = 1; // 1. wanted behavior (getA should not return a const reference)
    A otherA;
    b.getA() = otherA; // 2. unwanted

    return 0;
}
</code></pre>

Q: Partial specialization issue A: <p>logically speaking, since the &quot;type&quot; of request from network and local are different, you cannot have a single uniform interface to handle both of them. you'll need to</p>
<ul>
<li>use an enum like <code>Either&lt;L,R&gt;</code> to wrap them into the same type, or</li>
<li>use <code>Box&lt;dyn ...&gt;</code> to make it into a trait object, or</li>
<li>just use a field inside the the request struct <code>is_local_request: bool</code></li>
</ul>
<p>but here are some overthinking type-engineering.</p>
<h2>use seperate <code>run_net</code> and <code>run_net_local</code></h2>
<pre class="lang-rust prettyprint-override"><code>// Request and Response
struct Request;
struct Response;

// Application Traits
trait Application {
    fn serve(&amp;mut self, request: Request) -&gt; Response;
}
trait LocalApplication: Application {
    type LocalRequest;
    type LocalResponse;
    fn serve_local(&amp;mut self, request: Self::LocalRequest) -&gt; Self::LocalResponse;
}

// Actual Server Struct
struct Server&lt;A: Application&gt; {
    a: A,
}

impl&lt;A: Application&gt; Server&lt;A&gt; {
    pub fn serve(&amp;mut self, request: Request) -&gt; Response {
        self.a.serve(request)
    }
}

impl&lt;A: Application + LocalApplication&gt; Server&lt;A&gt; {
    pub fn serve_local(&amp;mut self, request: A::LocalRequest) -&gt; A::LocalResponse {
        self.a.serve_local(request)
    }
}

// Examples

// App1 with only Application impl
struct App1;
impl Application for App1 {
    fn serve(&amp;mut self, request: Request) -&gt; Response {
        Response
    }
}

// App2 with both Application and LocalApplication impl
struct App2;
impl Application for App2 {
    fn serve(&amp;mut self, request: Request) -&gt; Response {
        Response
    }
}
impl LocalApplication for App2 {
    type LocalRequest = u8;
    type LocalResponse = u8;
    fn serve_local(&amp;mut self, request: Self::LocalRequest) -&gt; Self::LocalResponse {
        0
    }
}

fn main() {
    let mut server1 = Server { a: App1 };
    let res: Response = server1.serve(Request); // OK
    let n: u8 = server1.serve_local(0);
    // the method `serve_local` exists for struct `Server&lt;App1&gt;`, but its trait bounds were not satisfied
    // the following trait bounds were not satisfied: `App1: LocalApplication`
    // items from traits can only be used if the trait is implemented and in scope

    let mut server2 = Server { a: App2 };
    let res: Response = server2.serve(Request); // OK
    let n: u8 = server2.serve_local(0); // OK

    server1.run_net([Request, Request, Request]);
    server2.run_net_local([Ok(Request), Err(0_u8), Ok(Request)]);
}

impl&lt;A: Application&gt; Server&lt;A&gt; {
    pub fn run_net(mut self, source: impl IntoIterator&lt;Item = Request&gt;) {
        for req in source {
            let _ = self.serve(req);
        }
    }
}
impl&lt;A: Application + LocalApplication&gt; Server&lt;A&gt; {
    pub fn run_net_local(
        mut self,
        source: impl IntoIterator&lt;Item = Result&lt;Request, A::LocalRequest&gt;&gt;,
    ) {
        for req in source {
            match req {
                Ok(r) =&gt; {
                    self.serve(r);
                }
                Err(r) =&gt; {
                    self.serve_local(r);
                }
            }
        }
    }
}
</code></pre>
<h2>tied request response type to <code>Application</code> instead</h2>
<pre class="lang-rust prettyprint-override"><code>trait Application {
    type Request;
    type Response;
    fn serve(&amp;mut self, req: Self::Request) -&gt; Self::Response;
}

struct NetworkRequest;
struct NetworkResponse;
struct LocalRequest;
struct LocalResponse;

enum EitherRequest {
    Network(NetworkRequest),
    Local(LocalRequest),
}
enum EitherResponse {
    Network(NetworkResponse),
    Local(LocalResponse),
}

// Actual Server Struct
struct Server&lt;A: Application&gt; {
    a: A,
}

struct App3;
impl Application for App3 {
    type Request = NetworkRequest;
    type Response = NetworkResponse;
    fn serve(&amp;mut self, req: Self::Request) -&gt; Self::Response {
        todo!()
    }
}

struct App4;
impl Application for App4 {
    type Request = EitherRequest;
    type Response = EitherResponse;
    fn serve(&amp;mut self, req: Self::Request) -&gt; Self::Response {
        todo!()
    }
}

fn main() {
    let mut server3 = Server { a: App3 };
    let _: NetworkResponse = server3.a.serve(NetworkRequest);

    let mut server4 = Server { a: App4 };
    let _: EitherResponse = server4.a.serve(EitherRequest::Network(NetworkRequest));
    let _: EitherResponse = server4.a.serve(EitherRequest::Local(LocalRequest));
}
</code></pre>
<h2>if you want request infer response</h2>
<pre class="lang-rust prettyprint-override"><code>trait Request {
    type Response;
}

trait Application&lt;R: Request&gt; {
    fn serve(&amp;mut self, req: R) -&gt; R::Response;
}

// Actual Server Struct
struct Server&lt;A&gt; {
    a: A,
}

struct NetworkRequest;
struct NetworkResponse;
impl Request for NetworkRequest {
    type Response = NetworkResponse;
}
struct LocalRequest;
struct LocalResponse;
impl Request for LocalRequest {
    type Response = LocalResponse;
}

struct App5;
impl Application&lt;NetworkRequest&gt; for App5 {
    fn serve(&amp;mut self, req: NetworkRequest) -&gt; NetworkResponse {
        todo!()
    }
}

struct App6;
impl Application&lt;NetworkRequest&gt; for App6 {
    fn serve(&amp;mut self, req: NetworkRequest) -&gt; NetworkResponse {
        todo!()
    }
}
impl Application&lt;LocalRequest&gt; for App6 {
    fn serve(&amp;mut self, req: LocalRequest) -&gt; LocalResponse {
        todo!()
    }
}

fn main() {
    let mut app5 = Server { a: App5 };
    let _: NetworkResponse = app5.a.serve(NetworkRequest);

    let mut app6 = Server { a: App6 };
    let _: NetworkResponse = app6.a.serve(NetworkRequest);
    let _: LocalResponse = app6.a.serve(LocalRequest);
}

</code></pre>
